	    di
	    ld   b, $F6
    in   a, (c)             ; port C: keep the cassette bits (4, 5)
	    and  $30
	    ld   d, a
	    ld   bc, $F40E
	    out  (c), c             ; port A = 14 (AY register number)
	    ld   b, $F6
	    or   $C0
