	    out  (c), c             ; port A becomes an input
	    pop  bc                 ; B = first row, C = count (the PPI ignores
	                            ; the low byte of its port address)
	    ld   a, d
	    or   $40                ; BC1 only = read
	    add  a, b
	    ld   e, a               ; E = port C value selecting the first row
__KS_LOOP:
	    ld   b, $F6
