__CKD_SHIFT:
	    ld   a, 1
	    inc  b
	    jr   __CKD_TEST
__CKD_LOOP:
	    add  a, a
__CKD_TEST:
	    djnz __CKD_LOOP         ; A = 1 << bit
	    and  (hl)
	    jr   nz, __CKD_NO       ; bit set = not pressed
	    ld   a, 1
	    ret
__CKD_NO:
	    xor  a
	    ret
	    ENDP

