	    and  (hl)
	    inc  hl
	    djnz __CAK_LOOP
	    inc  a                  ; $FF (nothing down) -> 0
	    ret  z
	    ld   a, 1
	    ret
	    ENDP

CB_KEYS:    defs 10         ; the last matrix scan, rows 0-9 (bit = 0: pressed)

