	    LOCAL __TXB_T, __TXB_W, __TXB_M0, __TXB_M1, __TXB_L0, __TXB_L1, __TXB_P0, __TXB_GP

    ld   hl, TX_TBUF        ; the table: no 256-byte boundary inside it
