	    cp   225
	    jr   c, __TXB_T
	    ld   de, 32
	    add  hl, de
__TXB_T:
	    ld   (TX_TP), hl
	    ld   a, l
	    ld   (__TXR_A1 + 1), a  ; patch the table's low byte into the row loops
	    ld   (__TXR_A2 + 1), a
	    ld   (__TXR_A3 + 1), a
	    ld   (__TXR_A4 + 1), a
	    ld   (__TXR_A5 + 1), a
	    ld   (__TXR_A6 + 1), a
	    ld   a, (GFX_XSHIFT)
	    ld   (TX_TMODE), a
