	    ld   c, (hl)            ; C = green * 16 + blue
	    inc  hl
	    ld   a, (hl)            ; A = red
	    inc  hl
	    add  a, a
	    add  a, a
	    add  a, a
	    add  a, a
	    ld   b, a               ; B = red * 16
	    ld   a, c
	    and  $0F
	    or   b
	    ld   (de), a
	    inc  de
	    ld   a, c
	    rrca
	    rrca
	    rrca
	    rrca
	    and  $0F
	    ld   (de), a
	    inc  de
	    pop  bc
	    djnz __PS_W
	    ret
	    ENDP

; __PC_APPLY -- HL = a record: writes its table rotated by its offset (entry
	; first + i gets table((i + offset) mod count)) in one block.
__PC_APPLY:
	    ld   e, (hl)
