	    ld   d, (hl)            ; DE = table
	    inc  hl
	    ld   a, (hl)
	    ld   (__PC_TE), a
	    inc  hl
	    ld   a, (hl)
	    ld   (__PC_TC), a
	    inc  hl
	    inc  hl
	    inc  hl
	    ld   a, (hl)
	    ld   (__PC_TO), a
	    add  a, a
	    ld   l, a
	    ld   h, 0
	    add  hl, de             ; HL = table + 2 * offset
	    push de                 ; the table
	    ld   de, __PC_BUF
	    ld   a, (__PC_TO)
	    ld   b, a
	    ld   a, (__PC_TC)
	    sub  b
	    ld   b, a               ; count - offset colours first
	    call __PC_SEG
