	    cp   2
    ret  c                  ; fewer than two colours: nothing to cycle
	    ld   a, (ix+7)
	    or   a
	    jr   z, __PE_STORE
	    ld   a, c
	    add  a, 16
	    ld   c, a
__PE_STORE:                 ; C = first entry, B = count
	    ld   a, (ix+5)
	    call __PC_REC           ; HL = record
	    ld   a, (ix+12)
	    ld   (hl), a
	    inc  hl
	    ld   a, (ix+13)
	    ld   (hl), a
	    inc  hl
	    ld   (hl), c            ; +2 first entry
	    inc  hl
	    ld   (hl), b            ; +3 count
	    inc  hl
	    ld   a, (ix+15)
	    or   a
	    jr   nz, __PE_STORE2
