__PE_STORE2:
	    ld   (hl), a            ; +4 period
	    inc  hl
	    ld   (hl), a            ; +5 frames left
	    inc  hl
	    xor  a
	    ld   (hl), a            ; +6 offset
	    inc  hl
	    ld   (hl), a            ; +7 forward
	    ld   a, (ix+5)
