	    jp   __PC_APPLY
	    ENDP

; __PC_DIR -- A = id, C = direction: PalCycleDir.
__PC_DIR:
	    cp   4
	    ret  nc
	    call __PC_REC
	    ld   de, 7
	    add  hl, de
	    ld   a, c
	    cp   3
	    jr   c, __PD_OK
	    xor  a
__PD_OK:
	    ld   (hl), a
	    ret

; __PC_STOP -- A = id: PalCycleStop.
__PC_STOP:
	    cp   4
	    ret  nc
	    call __PC_REC
	    inc  hl
	    inc  hl
	    inc  hl
	    ld   (hl), 0
	    ret

