	; __PL_SPRBASE -- A = sprite (masked to 0-15) -> HL = &6000 + 8 * sprite.
; Registers clobbered: AF.
__PL_SPRBASE:
	    and  $0F
	    add  a, a
	    add  a, a
	    add  a, a
	    ld   l, a
	    ld   h, $60
	    ret

