	; window of 5.4k T-states with interrupts off).
; Hardware: sprite pixel RAM, RMR2. Registers clobbered: AF, BC, DE, HL.
__PL_IMG:
	    ld   d, a
	    call __PL_ENSURE2
	    ret  nc
	    ld   a, d
	    and  $0F
	    or   $40
	    ld   d, a
	    ld   e, 0               ; DE = &4000 + 256 * sprite
	    ld   bc, 256
	    jp   __PL_PUT

