__IP_UN:                    ; PUSH writes a pixel pair, the left pixel (the byte's
	    ld   a, (hl)            ; high nibble) at the lower address. An interrupt
	    dec  hl                 ; pushes below SP, where the pairs are still to come.
	    ld   e, a
	    and  $0F
	    ld   d, a
	    ld   a, e
	    rrca
	    rrca
	    rrca
	    rrca
	    and  $0F
	    ld   e, a
	    push de
	    ld   a, (hl)
	    dec  hl
	    ld   e, a
	    and  $0F
	    ld   d, a
	    ld   a, e
	    rrca
	    rrca
	    rrca
	    rrca
	    and  $0F
