	    ld   (__SM_UP), hl
	    ld   hl, __SM_REC0
	    ld   de, __SM_REC0 + 1
	    ld   (hl), a
	    ld   bc, 159
	    ldir
	    ld   a, (__SM_COUNT)
	    or   a
	    ret  z
	    ld   b, a
	    ld   a, (__SM_FIRST)
	    ld   c, a
__SI_LOOP:                  ; hide the slots it owns
