	    ld   a, c
	    ld   e, 0
	    call __PL_MAGREG
	    pop  bc
	    inc  c
	    djnz __SI_LOOP
	    ret
	    ENDP

; __SM_ALLOC -- HL = picture, C = 0 (unpacked) or 2 (packed): A = a slot, or
	; 255. A free slot holding that picture is taken as it is; else the free slot
	; with no picture, else the one freed longest ago, gets an upload queued.
__SM_ALLOC:
	    PROC
	    LOCAL __SA_NONE, __SA_LOOP, __SA_CAND, __SA_AGE, __SA_SC, __SA_TAKE, __SA_NEXT, __SA_HIT
	    ld   a, h
	    or   l
	    jp   z, __SA_NONE
	    ld   a, (__SM_COUNT)
	    or   a
	    jp   z, __SA_NONE
	    ld   (__SM_TIMG), hl
	    ld   a, c
	    ld   (__SM_TPK), a
	    ld   a, 255
	    ld   (__SM_TBEST), a
	    ld   a, (__SM_FIRST)
	    ld   (__SM_TS), a
	    call __SM_REC
	    ld   (__SM_TREC), hl
	    ld   a, (__SM_COUNT)
	    ld   b, a
__SA_LOOP:
	    push bc
	    ld   hl, (__SM_TREC)    ; HL = record
	    ld   a, (hl)
	    and  __SM_USED
	    jp   nz, __SA_NEXT
	    push hl
	    inc  hl
	    inc  hl
	    ld   e, (hl)
	    inc  hl
	    ld   d, (hl)            ; DE = the slot's picture
	    ld   hl, (__SM_TIMG)
	    or   a
	    sbc  hl, de
	    pop  hl                 ; HL = record
	    jr   nz, __SA_CAND
	    ld   a, (hl)
	    and  __SM_PACK
	    ld   b, a
	    ld   a, (__SM_TPK)
	    cp   b
	    jp   z, __SA_HIT
__SA_CAND:                  ; a candidate: score 65535 if empty, else the age
	    inc  hl
	    inc  hl
	    ld   a, (hl)
	    inc  hl
	    or   (hl)               ; Z if no picture
	    inc  hl
	    ld   e, (hl)
	    inc  hl
	    ld   d, (hl)            ; DE = freed at
	    jr   nz, __SA_AGE
	    ld   hl, $FFFF
	    jr   __SA_SC
__SA_AGE:
	    ld   hl, (__SM_CLOCK)
	    or   a
	    sbc  hl, de             ; how long ago
	    ld   a, h
	    and  l
	    inc  a
	    jr   nz, __SA_SC
    dec  hl                 ; at most 65534: an empty slot always wins
__SA_SC:
	    ld   a, (__SM_TBEST)
	    inc  a
	    jp   z, __SA_TAKE       ; the first candidate
	    ld   de, (__SM_TSCORE)
	    ex   de, hl             ; HL = best so far, DE = this one
	    or   a
	    sbc  hl, de
    jp   nc, __SA_NEXT      ; this one is no older: keep the best
	    ex   de, hl
__SA_TAKE:
	    ld   (__SM_TSCORE), hl
	    ld   a, (__SM_TS)
	    ld   (__SM_TBEST), a
__SA_NEXT:
	    ld   a, (__SM_TS)
	    inc  a
	    ld   (__SM_TS), a
	    ld   hl, (__SM_TREC)
	    ld   de, 10
	    add  hl, de
	    ld   (__SM_TREC), hl
	    pop  bc
	    dec  b
	    jp   nz, __SA_LOOP
	    ld   a, (__SM_TBEST)
	    cp   255
	    ret  z
	    call __SM_REC           ; the chosen slot
	    ld   a, (__SM_TPK)
	    or   __SM_USED + __SM_PEND
	    ld   (hl), a
	    inc  hl
	    ld   (hl), 5
	    inc  hl
	    ld   de, (__SM_TIMG)
	    ld   (hl), e
	    inc  hl
	    ld   (hl), d
	    ld   hl, __SM_PENDN
	    inc  (hl)
	    ld   a, (__SM_TBEST)
	    ret
__SA_HIT:                   ; HL = record, BC still on the stack
	    ld   a, (__SM_TPK)
	    or   __SM_USED
	    ld   (hl), a
	    inc  hl
	    ld   (hl), 5
	    pop  bc
	    ld   a, (__SM_TS)
	    ret
__SA_NONE:
	    ld   a, 255
	    ret
	    ENDP

; __SM_FREE -- A = slot: SprFree.
__SM_FREE:
	    PROC
	    LOCAL __SF_KEEP, __SF_AGE, __SF_NOHIDE
	    call __SM_OWN
	    ret  nc
	    ld   (__SM_TS), a
	    call __SM_REC
	    ld   a, (hl)
	    and  __SM_USED
	    ret  z
	    ld   a, (hl)
	    and  __SM_SHOWN
	    jr   z, __SF_NOHIDE
	    ld   a, (__SM_TS)
	    ld   e, 0
	    call __PL_MAGREG
	    ld   a, (__SM_TS)
	    call __SM_REC
__SF_NOHIDE:
	    ld   a, (hl)
	    and  __SM_PEND
	    jr   z, __SF_KEEP
	    ld   hl, __SM_PENDN
	    dec  (hl)
    ld   a, (__SM_TS)       ; waiting for an upload: the slot holds nothing
	    call __SM_REC
