	    ld   (hl), a
	    inc  hl
	    inc  hl
	    ld   (hl), a
	    inc  hl
	    ld   (hl), a
	    jr   __SF_AGE
__SF_KEEP:                  ; keeps its picture (and whether it is packed)
	    ld   a, (hl)
	    and  __SM_PACK
	    ld   (hl), a
__SF_AGE:
