	    add  a, a
	    ld   e, a
	    ld   a, (ix+9)
	    call __PL_MAGCODE
	    or   e
	    ld   e, a
	    ld   a, (ix+7)
	    or   a
	    jr   z, __SG_OFF
	    ld   a, (ix+9)
	    or   a
	    jr   nz, __SG_GO
__SG_OFF:
	    ld   e, 0
__SG_GO:
