	    ld   de, 6
	    add  hl, de
	    ld   e, (hl)
	    inc  hl
	    ld   d, (hl)            ; DE = X
	    inc  hl
	    ld   c, (hl)
	    inc  hl
	    ld   b, (hl)            ; BC = Y
